import ast,hashlib,json,subprocess
from pathlib import Path
root=Path('/workspace')
runtime=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001']))
p=json.loads((root/'proposal.json').read_text())
def validate(x,s,path='"'$'"'):
 typ=s.get('type')
 if typ=='object':
  assert isinstance(x,dict),(path,'type')
  assert set(s.get('required',[]))<=set(x),(path,'required')
  if s.get('additionalProperties') is False:assert set(x)<=set(s.get('properties',{})),(path,'extra')
  for k,v in x.items():
   if k in s.get('properties',{}):validate(v,s['properties'][k],path+'.'+k)
 elif typ=='array':
  assert isinstance(x,list),(path,'type');assert len(x)>=s.get('minItems',0),(path,'minItems')
  for i,v in enumerate(x):validate(v,s.get('items',{}),f'{path}[{i}]')
 elif typ=='string':assert isinstance(x,str) and len(x)>=s.get('minLength',0),(path,'string')
 if 'const' in s:assert x==s['const'],(path,'const')
 if 'enum' in s:assert x in s['enum'],(path,'enum')
validate(p['study'],runtime['study_schema'])
assert p['study']['protocol_ref']==runtime['required_study_protocol_ref']
allowed=set(runtime['context']['allowed_observation_ids'])
assert set(p['study']['evidence_refs'])<=allowed
assert p['parent_trial'] in allowed
assert 1<=len(p['variants'])<=4
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert len({v['file'] for v in p['variants']})==len(p['variants'])
assert any(v['role']=='candidate' for v in p['variants'])
configs=[]
for v in p['variants']:
 assert set(v)=={'name','file','role','config','note'}
 assert v['role'] in ['candidate','control'] and Path(v['file']).name==v['file'] and v['file'].endswith('.py')
 source=(root/v['file']).read_text();tree=ast.parse(source);compile(tree,v['file'],'exec')
 config=ast.literal_eval(next(n.value for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets)))
 assert config==v['config']
 assert hashlib.sha256(source.encode()).hexdigest() in v['note']
 assert not set(config)&{'epochs','batch_size','train_seed','history_limit','learning_rate','precision','num_workers','data_dir','test'}
 configs.append((config['summary_action_alignment'],config['residual_routing']))
 assert config['summary_action_group']=='all' and config['action_in_pool'] is True and config['action_in_scorer'] is False
assert set(configs)=={(a,r) for a in ['aligned','rotated'] for r in ['task','shared']}
assert all(c['parent_ref'] in allowed for c in p['study']['contrasts'])
for a in p['knowledge_assessments']:
 assert a['decision'] in ['used','considered','rejected','unresolved']
 assert set(a['variant_names']) <= {v['name'] for v in p['variants']}
print('PASS: study schema, protocol identity, all evidence/parent IDs, variant manifest, literal configs, hashes, complete2x2 and knowledge assessments')
print('Main files:',', '.join(['proposal.json']+[v['file'] for v in p['variants']]))
print('No training, installation, held-out request, or host contract edits performed.')
PY"

